; cputime_test.asm - generated by make_cputime_test.py: 6809 instruction cycles and VIA timing, one page.
; Build: lwasm --format=raw -o cputime_test_raw.bin cputime_test.asm, then pad to 32768 bytes with $FF.

Wait_Recal      equ $F192
Intensity_a     equ $F2AB
Reset0Ref       equ $F354
Print_Str_d     equ $F37A
Vec_Text_HW     equ $C82A
VIA_t1_cnt_lo   equ $D004

Vals            equ $C880           ; 32 results
RowBuf          equ $C980           ; the 16 rows as strings, 26 bytes each
Buf             equ $C900           ; the indexed tests' data (a pointer to itself at $C900)
Idx             equ $C8F0
PosY            equ $C8F1
Base            equ $C8F2

        org     $0000
        fcc     "g GCE 2026"
        fcb     $80
        fdb     $FD0D
        fcb     $F8,$50,$20,-$40
        fcc     "CPU TIMING"
        fcb     $80
        fcb     0

Start:
        ldd     #Buf
        std     Buf                 ; ([,X] reads through it)
        ldy     #T_base
        jsr     Meas
        stb     Base
        ldy     #T_i0
        jsr     Meas
        negb
        addb    Base
        stb     Vals+0
        ldy     #T_i1
        jsr     Meas
        negb
        addb    Base
        stb     Vals+1
        ldy     #T_i2
        jsr     Meas
        negb
        addb    Base
        stb     Vals+2
