        addb    Base
        stb     Vals+6
        ldy     #T_i7
        jsr     Meas
        negb
        addb    Base
        stb     Vals+7
        ldy     #T_i8
        jsr     Meas
        negb
        addb    Base
        stb     Vals+8
        ldy     #T_i9
        jsr     Meas
        negb
        addb    Base
        stb     Vals+9
        ldy     #T_i10
        jsr     Meas
        negb
        addb    Base
        stb     Vals+10
        ldy     #T_i11
        jsr     Meas
        negb
        addb    Base
        stb     Vals+11
        ldy     #T_i12
        jsr     Meas
        negb
        addb    Base
        stb     Vals+12
        ldy     #T_i13
        jsr     Meas
        negb
        addb    Base
        stb     Vals+13
        ldy     #T_i14
        jsr     Meas
        negb
        addb    Base
        stb     Vals+14
        ldy     #T_i15
        jsr     Meas
        negb
        addb    Base
        stb     Vals+15
        jsr     T_v0
        sta     Vals+16
        jsr     T_v1
        sta     Vals+17
        jsr     T_v2
        sta     Vals+18
        jsr     T_v3
        sta     Vals+19
        jsr     T_v4
        sta     Vals+20
        jsr     T_v5
        sta     Vals+21
        jsr     T_v6
        sta     Vals+22
        jsr     T_v7
        sta     Vals+23
        jsr     T_v8
        sta     Vals+24
        jsr     T_v9
        sta     Vals+25
        jsr     T_v10
        sta     Vals+26
        jsr     T_v11
        sta     Vals+27
        jsr     T_v12
        sta     Vals+28
        jsr     T_v13
        sta     Vals+29
        jsr     T_v14
        sta     Vals+30
        jsr     T_v15
        sta     Vals+31
        jsr     MakeRows

Main:
        jsr     Wait_Recal
        ldd     #$F838
        std     Vec_Text_HW
        lda     #$7F
        jsr     Intensity_a
        jsr     Reset0Ref
        lda     #$7F
        sta     VIA_t1_cnt_lo
        ldu     #RowBuf+0
        ldd     #$2094
        jsr     Print_Str_d
        jsr     Reset0Ref
        lda     #$7F
        sta     VIA_t1_cnt_lo
        ldu     #RowBuf+26
        ldd     #$0094
        jsr     Print_Str_d
        jsr     Reset0Ref
        lda     #$7F
        sta     VIA_t1_cnt_lo
        ldu     #RowBuf+52
        ldd     #$E094
        jsr     Print_Str_d
        jsr     Reset0Ref
        lda     #$7F
        sta     VIA_t1_cnt_lo
        ldu     #RowBuf+78
        ldd     #$C094
        jsr     Print_Str_d
        jmp     Main

; MakeRows - the row templates to RAM, the values into them in hex
MakeRows:
        ldx     #RowTpl
        ldu     #RowBuf
        ldy     #104
@c      lda     ,x+
        sta     ,u+
        leay    -1,y
        bne     @c
        ldu     #RowBuf+2
        lda     Vals+0
        jsr     PutHex
        ldu     #RowBuf+5
        lda     Vals+1
        jsr     PutHex
        ldu     #RowBuf+8
        lda     Vals+2
        jsr     PutHex
        ldu     #RowBuf+11
        lda     Vals+3
        jsr     PutHex
        ldu     #RowBuf+14
        lda     Vals+4
        jsr     PutHex
        ldu     #RowBuf+17
        lda     Vals+5
        jsr     PutHex
        ldu     #RowBuf+20
