        jsr     PutHex
        ldu     #RowBuf+60
        lda     Vals+18
        jsr     PutHex
        ldu     #RowBuf+63
        lda     Vals+19
        jsr     PutHex
        ldu     #RowBuf+66
        lda     Vals+20
        jsr     PutHex
        ldu     #RowBuf+69
        lda     Vals+21
        jsr     PutHex
        ldu     #RowBuf+72
        lda     Vals+22
        jsr     PutHex
        ldu     #RowBuf+75
        lda     Vals+23
        jsr     PutHex
        ldu     #RowBuf+80
        lda     Vals+24
