        ldu     #RowBuf+98
        lda     Vals+30
        jsr     PutHex
        ldu     #RowBuf+101
        lda     Vals+31
        jsr     PutHex
        rts

PutHex:
        pshs    a
        lsra
        lsra
        lsra
        lsra
        jsr     Nib
        sta     ,u+
        puls    a
        anda    #$0F
        jsr     Nib
        sta     ,u
        rts

; Meas - time the routine at Y with timer 2: B = timer 2 low byte after it (counting down from $FF)
Meas:
        ldx     #Buf
        lda     #$FF
        sta     $D008               ; timer 2 low latch
        sta     $D009               ; high: load, start
        jsr     ,y
        ldb     $D008
        rts

T_base:
        rts

Sub:
        rts

T_i0:                               ; NOP
        nop
        rts

T_i1:                               ; MUL
        mul
        rts

T_i2:                               ; PSH PUL
        pshs    cc,a,b,dp,x,y,u
        puls    cc,a,b,dp,x,y,u
        rts

T_i3:                               ; LDA ,X
        lda     ,x
        rts

T_i4:                               ; LDA 1,X
        lda     1,x
        rts

T_i5:                               ; LDA ,X+
        lda     ,x+
        rts

T_i6:                               ; LDA [,X]
        lda     [,x]
        rts

T_i7:                               ; LDA D,X
        lda     d,x
        rts

T_i8:                               ; LDA A,X
        lda     a,x
        rts

T_i9:                               ; LBRA
        lbra    @t
@t
        rts

T_i10:                               ; CLR LBEQ
        clra
        lbeq    @t
@t
        rts

T_i11:                               ; LD1 LBEQ
        lda     #1
        lbeq    @t
@t
        rts

T_i12:                               ; JSR RTS
        jsr     Sub
        rts

T_i13:                               ; EXG X,Y
        exg     x,y
        rts

T_i14:                               ; TFR X,Y
        tfr     x,y
        rts

T_i15:                               ; LEAX 1,X
        leax    1,x
        rts

T_v0:                               ; T1 RD 0
        lda     #$40
        sta     $D004
        ldb     #0
        stb     $D005
        lda     $D004
        rts

T_v1:                               ; T1 RD 2
        lda     #$40
        sta     $D004
        ldb     #0
        stb     $D005
        nop
        lda     $D004
        rts

T_v2:                               ; T1 WRAP
        lda     #$04
        sta     $D004
